/* ------------------------------------------------------------------
   Foclóir IRS139 — vocabulary data
   ------------------------------------------------------------------
   One object per entry:
     ga    Irish (required)
     en    English (required)
     cat   category key — see CATS below (required)
     note  grammar point, etymology or anecdote (optional)
     see   array of related Irish headwords, for the "linked" chips
     noq   true = leave this one out of the quiz (phrases too long,
           or items where there is no single right answer)

   To add a week: paste new objects at the bottom of VOCAB. Nothing
   else needs changing — the counts, filters, decks and quiz all
   build themselves from this array.
   ------------------------------------------------------------------ */

const CATS = {
  beatha:    { name: "Caint laethúil",      en: "Everyday speech" },
  tuairim:   { name: "Tuairimí",            en: "Opinion & argument" },
  mothu:     { name: "Mothúcháin",          en: "Feelings & states" },
  am:        { name: "Am",                  en: "Time" },
  gram:      { name: "Gramadach",           en: "Grammar patterns" },
  teanga:    { name: "Teangeolaíocht",      en: "Language & sound" },
  coláiste:  { name: "Coláiste",            en: "College & learning" },
  stair:     { name: "Stair is polaitíocht", en: "History & politics" },
  áit:       { name: "Áiteanna",            en: "Places & directions" },
  focail:    { name: "Focail bhunúsacha",   en: "Core words" },
  nath:      { name: "Nathanna",            en: "Idioms & sayings" },
};

const VOCAB = [

/* ============ CAINT LAETHÚIL ============ */
{ ga:"ar siúl", en:"going on, in progress", cat:"beatha",
  note:"Literally “on walking”. <b>Cad é atá ar siúl?</b> = what's going on? Compare <i>ar bun</i> (under way) and <i>ar fáil</i> (available) — Irish builds a lot of states out of <i>ar</i> + a bare noun.", see:["ar bun","Le fáil"] },
{ ga:"Ba mhór againn é", en:"we would greatly appreciate it", cat:"beatha",
  note:"Copula + <i>mór</i> + <i>ag</i>. Present: <b>is mór againn é</b>. The same frame gives <i>is beag orm é</i> (I can't stand it) and <i>is cuma liom</i> (I don't care).", see:["is cuma i ndáiríre","is olc leo / is lúcháireach leo"] },
{ ga:"tar éis é sin", en:"after that", cat:"am",
  note:"More idiomatic: <b>ina dhiaidh sin</b>. <i>Tar éis</i> + verbal noun also gives the perfect: <i>tar éis teacht</i> = having just come. In Ulster you'll hear <i>i ndiaidh</i> instead of <i>tar éis</i> throughout." },
{ ga:"áit éigin", en:"somewhere", cat:"beatha",
  note:"<i>Éigin</i> = some: <i>duine éigin, rud éigin, lá éigin, áit éigin</i>. Same root as <i>éigean</i> (compulsion) and <i>ar éigean</i> (barely).", see:["b’éigean dom"] },
{ ga:"lá fada go leor ach bhí sé thar barr", en:"quite a long day but it was great", cat:"beatha",
  note:"<b>go leor</b> after an adjective means “fairly, quite”, not “enough”. <b>thar barr</b> = over the top, in the good sense.", noq:true },
{ ga:"ar dóigh", en:"wonderful, great", cat:"beatha",
  note:"Ulster. Standard <i>ar fheabhas</i>. <i>Dóigh</i> = way, manner — so literally “in (good) order”. The same word gives <i>cén dóigh?</i> (how?) and <i>is dóigh liom</i> (I think).", see:["is dóigh liom","Cén dóigh"] },
{ ga:"samhlaigh é sin", en:"imagine that", cat:"beatha",
  note:"<i>Samhail</i> = a likeness → <i>samhlaigh</i> imagine, <i>samhlaíocht</i> imagination. <b>Samhlaítear dom go…</b> = it strikes me that… — the gentlest of the “it seems to me” family.", see:["Feictear dom / tchítear dom"] },
{ ga:"molaim go bun na spéire é", en:"I highly recommend it", cat:"nath",
  note:"Literally “I praise it to the bottom of the sky”, i.e. all the way to the horizon. <i>Bun na spéire</i> is the skyline, where sky meets ground.", see:["Mol"] },
{ ga:"in áirithe", en:"reserved, booked", cat:"beatha",
  note:"<b>áit a chur in áirithe</b> = to book a place. Same word as <i>go háirithe</i> (especially) and <i>áirithe</i> (certain, particular) — all from <i>áireamh</i>, counting or reckoning.", see:["Áirithe","go háirid / go háirithe"] },
{ ga:"Tá neart daoine ann", en:"there are plenty of people", cat:"beatha",
  note:"<i>Neart</i> is literally strength. Strength → abundance is a common shift; English “a power of people” does the same thing." },
{ ga:"Comhghairdeas leat!", en:"congratulations!", cat:"beatha",
  note:"<i>comh-</i> (together, co-) + <i>gairdeas</i> (rejoicing) — rejoicing-with, exactly like Latin <i>con-gratulari</i>." },
{ ga:"Tá sé beagnach am", en:"it's nearly time", cat:"am" },
{ ga:"Ní fheadar cá bhfuil siad anois", en:"I wonder where they are now", cat:"beatha",
  note:"<i>Ní fheadar</i> is a Munster survival — a defective verb with no other tenses, meaning “I don't know / I wonder”. Ulster would say <i>chan fhuil a fhios agam</i>. Worth recognising, not worth imitating in Ulster Irish." },
{ ga:"tá sé i ngar duit go leor", en:"it's very close to you", cat:"áit", see:["Gar"] },
{ ga:"Go n-éirí leat!", en:"good luck!", cat:"beatha",
  note:"Literally “may it rise with you”. <i>Éirigh le</i> = to succeed: <i>d'éirigh go maith leis</i> = he did well. The full blessing is <i>go n-éirí an bóthar leat</i> — may the road rise with you." },
{ ga:"Céard atá i gceist agat?", en:"what do you mean?", cat:"beatha",
  note:"<i>Céard</i> is Connacht; Ulster says <b>cad é atá i gceist agat?</b> <i>I gceist</i> = at issue, in question.", see:["Cén dóigh"] },
{ ga:"Ba mhaith liom an méid is lú", en:"I'd like the smaller amount", cat:"beatha",
  note:"<i>Is lú</i> is the superlative of <i>beag</i>, used here where English prefers a comparative. Irish often reaches for the superlative with two items." },
{ ga:"I ndáiríre, is cuma!", en:"really, it doesn't matter!", cat:"beatha", see:["is cuma i ndáiríre"] },
{ ga:"cibé rud atá againn", en:"whatever we have", cat:"gram",
  note:"<i>Cibé</i> and <i>pé</i> are interchangeable: whatever, whoever, whichever.", see:["Pé","Pé hé féin"] },
{ ga:"Cuirfidh mé scairt ort", en:"I'll give you a ring", cat:"beatha",
  note:"Ulster. <i>Scairt</i> is a shout or call — you literally put a shout on somebody. Standard: <b>cuirfidh mé glaoch ort</b>." },
{ ga:"díreach tosaithe", en:"just started", cat:"am", see:["ag toiseacht"] },
{ ga:"spraíúil agus spreagtha", en:"fun and inspiring", cat:"beatha",
  note:"<i>Spreag</i> = to inspire, prompt, encourage; <i>spreagtha</i> is its verbal adjective.", see:["A bheith in ann iad a spreagadh"] },
{ ga:"comhrá scaoilte", en:"relaxed conversation", cat:"beatha",
  note:"<i>Scaoilte</i> = loosed, untied. A loose conversation is an unbuttoned one.", see:["Scaoil"] },
{ ga:"Fíorchomhrá", en:"genuine conversation", cat:"beatha",
  note:"<i>fíor-</i> (true, real) is a live prefix: <i>fíorscéal</i> true story, <i>fíoruisce</i> spring water, <i>fíorbheagán</i> very little." },
{ ga:"Aipeanna", en:"apps", cat:"beatha",
  note:"A modern borrowing, naturalised with the plural <i>-eanna</i>. Irish absorbs loanwords by giving them a native ending — the same thing happened to <i>veain, buidéal, seomra</i> centuries ago." },
{ ga:"Closleabhar", en:"audiobook", cat:"coláiste",
  note:"<i>clos-</i> (hearing, from <i>cloisteáil</i>) + <i>leabhar</i>. The same prefix gives <i>closamharc</i> (audiovisual)." },
{ ga:"chun cabhrú liom", en:"to help me", cat:"gram",
  note:"<i>Chun</i> + verbal noun = in order to. Ulster prefers <i>cuidiú liom</i> to <i>cabhrú liom</i>.", see:["Cuidigh / cúnaigh"] },
{ ga:"Fós", en:"still, yet", cat:"am",
  note:"Positive = still (<i>tá sé anseo fós</i>); negative = yet (<i>níl sé anseo fós</i>). The word does double duty." },
{ ga:"cuir in iúl", en:"to indicate, to make known", cat:"beatha",
  note:"<i>Iúl</i> = knowledge, guidance. <b>Chuir sé in iúl dom go…</b> = he let me know that… Useful in formal writing and email." },
{ ga:"Is fiú an t-airgead é", en:"it's worth the money", cat:"beatha", see:["B’fhiú do dhaoine…"] },
{ ga:"B’fhiú do dhaoine…", en:"it would be worth people's while to…", cat:"tuairim",
  note:"<i>Is fiú</i> → past/conditional <i>b'fhiú</i>. Negative: <b>ní fiú</b> = there's no point." },
{ ga:"Bua na cainte", en:"the gift of the gab", cat:"nath",
  note:"<i>Bua</i> = victory, gift, talent — the same word in <i>bua a fháil ar</i> (to defeat). The English phrase has its own Irish source story: Cormac Mac Cárthaigh of Blarney Castle talked Elizabeth I's deputy in circles for so long that “Blarney” entered English as flattering talk." },

/* ============ TUAIRIMÍ ============ */
{ ga:"gan amhras", en:"without a doubt", cat:"tuairim", see:["Amhras"] },
{ ga:"Is iondúil (go)", en:"it is usual / customary that", cat:"tuairim" },
{ ga:"Go hiondúil", en:"usually", cat:"am", see:["Is iondúil (go)"] },
{ ga:"i dtaca liomsa de", en:"as far as I'm concerned", cat:"tuairim",
  note:"<i>Taca</i> = support, prop. The emphatic <i>liomsa</i> is doing real work here: it marks this as <i>my</i> view, whatever anyone else thinks.", see:["um an dtaca seo"] },
{ ga:"níl a leithéid de rud ann", en:"there's no such thing", cat:"tuairim",
  note:"<i>A leithéid</i> = the like of it. <b>A leithéid de lá!</b> = what a day! <i>Leith</i> = a half or a side, so a <i>leithéid</i> is literally its other half, its match." },
{ ga:"is cuma i ndáiríre", en:"it doesn't really matter", cat:"tuairim", see:["Is ríchuma liom"] },
{ ga:"ní hionann X agus Y", en:"X and Y are not the same thing", cat:"tuairim",
  note:"The single most useful essay phrase on this list. Positive: <b>is ionann X agus Y</b>. <i>Ní</i> prefixes <i>h</i> to the vowel. Also <b>is ionann iad</b> = they are the same.", see:["is ionann X agus Y","is mór idir sin agus…"] },
{ ga:"is ionann X agus Y", en:"X is the same as Y", cat:"tuairim", see:["ní hionann X agus Y"] },
{ ga:"is mór idir sin agus…", en:"there's a big difference between that and…", cat:"tuairim",
  note:"Literally “it is great between that and…”. A tighter, more literary alternative to <i>tá difear mór idir</i>." },
{ ga:"i gcomórtas le", en:"compared with", cat:"tuairim",
  note:"<i>Comórtas</i> = competition, comparison. Also <b>i gcomparáid le</b>." },
{ ga:"ó thaobh X de", en:"from the point of view of X", cat:"tuairim",
  note:"Takes the genitive: <i>ó thaobh na gramadaí de</i>. One of the handiest essay frames there is — it lets you signpost each angle in turn." },
{ ga:"is dóigh liom", en:"I think, I suppose", cat:"tuairim",
  note:"Tentative. The ladder, from softest to firmest: <i>samhlaítear dom</i> → <i>feictear dom</i> → <i>is dóigh liom</i> → <i>dar liom</i> → <i>measaim</i> → <i>táim cinnte</i>.", see:["Feictear dom / tchítear dom"] },
{ ga:"Feictear dom / tchítear dom", en:"it appears to me", cat:"tuairim",
  note:"<i>Feictear</i> is the autonomous present of <i>feic</i> — literally “it is seen to me”. <i>Tchítear</i> is the Ulster form (also written <i>chítear</i>); fully Ulster you'd write <b>tchítear domh</b>. Past: <b>chonacthas dom</b>, which is what Antain says in the Week 1 script.", see:["is dóigh liom"] },
{ ga:"is cosúil gur", en:"it seems that", cat:"tuairim",
  note:"<i>Cosúil le</i> = like, similar to; <i>cosúlacht</i> = appearance, likelihood." },
{ ga:"más fíor", en:"supposedly, allegedly", cat:"tuairim",
  note:"Literally “if it's true”, thrown in to distance yourself from a claim. <i>Más</i> = <i>má</i> + the copula." },
{ ga:"a mhinice agus is féidir", en:"as often as possible", cat:"tuairim",
  note:"<i>Minic</i> → the abstract noun <i>a mhinice</i>, “its frequency”. Same pattern: <i>a laghad</i> (how few), <i>a mhéad</i> (how many), <i>a fhad</i> (how long).", see:["is minic a"] },
{ ga:"ó tharla go", en:"since, given that", cat:"tuairim",
  note:"Literally “since it happened that”. Alternatives: <i>ós rud é go</i>, <i>cionn is go</i> (Ulster), <i>toisc go</i>." },
{ ga:"Bíodh sé cóir nó éagóir", en:"be it right or wrong", cat:"tuairim",
  note:"<i>Bíodh</i> is the imperative of <i>bí</i> used concessively — “let it be…”. <i>Cóir</i> = just; <i>éagóir</i> = injustice, with the negative prefix <i>éa-</i>." },
{ ga:"is ró-mhaith atá a fhios agamsa", en:"I know only too well", cat:"nath",
  note:"Fronted for emphasis, with <i>ró-</i> (too) and the emphatic <i>agamsa</i>. Carries a weary note, same as the English." },
{ ga:"Is ríchuma liom", en:"I couldn't care less", cat:"tuairim",
  note:"<i>rí-</i> is an intensifying prefix from <i>rí</i> (king) — king-sized. Also <i>ríshásta</i> (delighted), <i>ríthábhachtach</i> (crucial).", see:["is cuma i ndáiríre"] },
{ ga:"is olc leo / is lúcháireach leo", en:"they resent it / they rejoice at it", cat:"tuairim",
  note:"Copula + adjective + <i>le</i> is a whole family of attitude verbs: <i>is maith liom</i> (I like), <i>is fuath liom</i> (I hate), <i>is fearr liom</i> (I prefer), <i>is cuma liom</i> (I don't care), <i>is doiligh liom</i> (I find it hard)." },
{ ga:"Dearc ort féin", en:"reflect on yourself", cat:"tuairim",
  note:"<i>Dearc ar</i> = to look at, to consider — the verb behind <i>dearcadh</i>, outlook.", see:["Dearcadh"] },
{ ga:"impím ar", en:"I implore, I beg (of)", cat:"tuairim",
  note:"<i>Impigh ar dhuine rud a dhéanamh</i>. High register — rhetoric, prayer, pleading." },
{ ga:"cáineadh", en:"criticism, condemnation", cat:"tuairim",
  note:"Verb <i>cáin</i> = to criticise, condemn. Not to be confused with the noun <i>cáin</i> = tax (<i>An Coimisinéir Cánach</i>)." },
{ ga:"contrártha leis sin", en:"contrary to that", cat:"tuairim",
  note:"Also <b>a chontrárthacht sin</b> = the contrary of that. From Latin <i>contrarius</i>." },
{ ga:"gan mhaith", en:"worthless, useless", cat:"tuairim",
  note:"<i>Gan</i> lenites a following noun in set phrases like this: <i>gan mhaith, gan mhoill</i> (without delay), <i>gan amhras</i> (which keeps the vowel, so no change shows)." },
{ ga:"cuir in éadan", en:"to oppose", cat:"stair",
  note:"<i>Éadan</i> = forehead, face, front — so opposing is literally fronting up to something. Ulster uses <i>in éadan</i> where the standard often has <i>i gcoinne</i>.", see:["in éadan","Agóid"] },
{ ga:"cuir bac le", en:"to prevent, hinder, block", cat:"stair",
  note:"<i>Bac</i> = a baulk, an obstacle. Also <b>ná bac leis</b> = don't bother with it, pay it no heed — one of the most-used phrases in spoken Irish." },

/* ============ MOTHÚCHÁIN ============ */
{ ga:"Tá éad orm", en:"I'm jealous", cat:"mothu",
  note:"Feelings sit <i>on</i> you in Irish. The second preposition varies and has to be learned per feeling: jealous <i>of</i> = <b>in éad le</b>.", see:["tá an-díomá orm"] },
{ ga:"tá an-díomá orm", en:"I'm very disappointed", cat:"mothu",
  note:"<i>Díomá</i> (disappointment) takes <i>faoi</i> for the cause: <i>tá díomá orm faoin toradh</i>." },
{ ga:"Róthógtha le", en:"too fond of, too taken with", cat:"mothu",
  note:"<i>Tógtha le</i> = taken with. <i>Ró-</i> lenites: <i>rómhall, ródhaor, róthógtha</i>; before a vowel it takes a hyphen: <i>ró-ard</i>." },
{ ga:"goilleann sin ort", en:"that hurts you, that upsets you", cat:"mothu",
  note:"<i>Goill ar</i> — the pain acts on you rather than you feeling it. <i>Ghoill a bhás go mór uirthi</i> = his death affected her badly." },
{ ga:"Gráin", en:"hatred, loathing", cat:"mothu",
  note:"<b>Tá an ghráin agam ar X</b> = I hate X. The same word also means ugliness, which is the hinge of the proverb below.", see:["Folaíonn grá gráin","fuath na n-ae"] },
{ ga:"fuath na n-ae", en:"visceral hatred", cat:"nath",
  note:"Literally “hatred of the livers”. The liver, not the heart, was the old seat of strong feeling in Irish — compare <i>mo chuisle</i> (my pulse) and <i>a chroí</i> for affection. Greek and Latin did the same with the liver." },
{ ga:"bá ag X le Y", en:"X has sympathy for Y", cat:"tuairim",
  note:"<i>Bá</i> = sympathy, fellow-feeling. <b>Tá bá agam leo</b>. A different word from <i>bá</i> = drowning, and from <i>bá</i> = a bay." },
{ ga:"Croíúil", en:"hearty, cordial", cat:"mothu",
  note:"From <i>croí</i> (heart) — the exact same metaphor as English “hearty”. <i>Fáilte chroíúil</i> = a warm welcome." },
{ ga:"ag súil leis", en:"looking forward to it", cat:"mothu",
  note:"<i>Súil</i> = eye, and also expectation — you have your eye on it. <b>Tá mé ag súil go mór leis</b> = I'm really looking forward to it; <b>ag súil le duine</b> can also mean expecting someone." },
{ ga:"Tá muid faoi chomaoin acu", en:"we are indebted to them", cat:"mothu",
  note:"<i>Comaoin</i> = a favour, an obligation. <b>Comaoin a chur ar dhuine</b> = to put someone in your debt. (The sheet glosses this as “I am indebted”, but <i>tá muid</i> is “we are”.)" },
{ ga:"Níl muid inár n-aonar", en:"we are not alone", cat:"mothu",
  note:"<i>I</i> + possessive + <i>aonar</i>: <i>i m'aonar</i>, <i>i d'aonar</i>, <i>ina aonar</i>, <i>inár n-aonar</i>. The same slot that gives <i>ina sheasamh</i> and <i>ina chodladh</i>.", see:["Bhí sé ina sheasamh os mo chomhair"] },
{ ga:"I ndlúthpháirtíocht", en:"in solidarity", cat:"stair",
  note:"<i>dlúth</i> (close, tight) + <i>páirtíocht</i> (partnership). The same <i>dlúth-</i> gives <i>dlúthchuid</i> (integral part) and <i>dlúthdhiosca</i> (CD).", see:["dlúthchuid"] },

/* ============ AM ============ */
{ ga:"le bliain anuas", en:"for the past year", cat:"am",
  note:"<i>Anuas</i> is “down from above”, and Irish treats elapsed time as coming down towards now: <i>le seachtain anuas</i>, <i>le blianta anuas</i>. For time going forward you'd use <i>as seo amach</i>." },
{ ga:"le gairid", en:"recently", cat:"am", see:["ar na mallaibh","ar na saolta deireanacha"] },
{ ga:"ar na mallaibh", en:"recently, lately", cat:"am",
  note:"Ulster. <i>Mallaibh</i> is an old dative plural of <i>mall</i> (late, slow) — a fossil form that survives only in this phrase." },
{ ga:"ar na saolta deireanacha", en:"in recent times", cat:"am",
  note:"Literally “in the latter lifetimes”. <i>Saol</i> covers both life and world, so <i>an saol mór</i> is everybody." },
{ ga:"um an dtaca seo", en:"by this time, by now", cat:"am",
  note:"Also <b>faoin taca seo</b>. Note the eclipsis after <i>um an</i> — a fossil of the older rule, preserved only in fixed phrases like this one.", see:["Um"] },
{ ga:"sa chéad seo", en:"in this century", cat:"am",
  note:"<i>Céad</i> here is “a hundred” → a century. Mind the three homographs: <i>céad</i> (hundred), <i>céad</i> (first) and <i>céad</i> in <i>céad míle fáilte</i>." },
{ ga:"lenár linn féin", en:"in our own time", cat:"am", see:["Le linn"] },
{ ga:"Le linn", en:"during, in the course of", cat:"am",
  note:"Takes the genitive: <i>le linn an chogaidh</i>. <i>Linn</i> here is a period or span. With a pronoun it fuses: <i>lena linn</i> = during it, <i>le mo linn</i> = in my time." },
{ ga:"Thart fá", en:"around, about", cat:"am",
  note:"Ulster, for both place and approximation: <i>thart fá Bhéal Feirste</i>, <i>thart fá chéad duine</i>. Standard: <i>timpeall ar</i>." },
{ ga:"Na nóchaidí", en:"the nineties", cat:"am",
  note:"Decades take the plural of the number: <i>na seachtóidí, na hochtóidí, na nóchaidí</i>. His sheet writes “na 90ídí”, which is how people often jot it." },
{ ga:"Go deo", en:"forever", cat:"am",
  note:"In negative sentences it flips to “never again”: <i>ní rachaidh mé ann go deo</i>. Also <i>go brách</i> and <i>go deo na ndeor</i> (for ever and ever, literally “to the eternity of tears”)." },
{ ga:"Síoraí", en:"eternal, perpetual, continual", cat:"focail",
  note:"<i>An tSíoraíocht</i> = eternity. Often worn down to “constant, endless” in complaints: <i>an caint shíoraí seo</i> — this endless talk." },
{ ga:"ar an toirt", en:"instantly, on the spot", cat:"am",
  note:"<i>Toirt</i> = bulk, mass — the idea is “in the one lump of time”." },
{ ga:"corruair", en:"occasionally, now and then", cat:"am",
  note:"<i>corr-</i> = odd, occasional, and it's productive: <i>corrdhuine</i> (the odd person), <i>corrfhocal</i> (the odd word), <i>corrlá</i> (the odd day).", see:["corr","corrdhuine"] },
{ ga:"in amanna", en:"at times", cat:"am",
  note:"Ulster, for standard <i>uaireanta</i>. <i>Aimsir</i> covers time, weather and grammatical tense all at once.", see:["i ngach aimsir"] },
{ ga:"i bhfad siar", en:"long ago, far back", cat:"am",
  note:"<i>Siar</i> is westward — and also backward, in space and in time. Irish lays time out east-to-west, with the past to the west." },
{ ga:"Riamh", en:"ever, never, before", cat:"gram",
  note:"Used only of the past. Positive = ever (<i>an raibh tú ann riamh?</i>), negative = never (<i>ní raibh mé ann riamh</i>). For the future you need <i>choíche</i> or <i>go deo</i>.", see:["Riamh nó iaramh"] },
{ ga:"Riamh nó iaramh", en:"before or since, ever at all", cat:"nath",
  note:"A rhyming pair, like “by hook or by crook” — the second word exists mainly to chime with the first. <i>Iaramh</i> is from <i>iar</i> (after)." },

/* ============ GRAMADACH ============ */
{ ga:"cé go raibh", en:"although it was", cat:"gram",
  note:"<i>Cé go</i> + eclipsis; negative <b>cé nach</b>. With the copula: <i>cé gur</i>. Don't confuse with <i>cé</i> = who." },
{ ga:"tá sé doiligh", en:"it is hard", cat:"gram",
  note:"Ulster <i>doiligh</i> = standard <i>deacair</i>. With the copula: <b>is doiligh é a dhéanamh</b> = it's hard to do.", see:["Furasta"] },
{ ga:"An tír a bhreathnú", en:"to view the country", cat:"gram",
  note:"The backbone pattern of Irish: <b>object + a + lenited verbal noun</b>. <i>An tír a bhreathnú, an Ghaeilge a fhoghlaim, í a labhairt</i>. English puts the object second; Irish puts it first.", see:["Breathnaigh"] },
{ ga:"chomh maith le", en:"as good as; as well as", cat:"gram",
  note:"<b>chomh + adjective + le</b> before a noun, but <b>chomh + adjective + agus/is</b> before a clause: <i>chomh furasta is atá sé</i>." },
{ ga:"le go mbeidh", en:"so that (something) will be", cat:"gram",
  note:"<i>Le go</i> + eclipsis for purpose. Also <b>sa dóigh is go</b> (Ulster) and <b>ionas go</b>.", see:["sa dóigh is go"] },
{ ga:"sa dóigh is go", en:"so that, in such a way that", cat:"gram",
  note:"Ulster. Standard <i>ionas go</i> / <i>sa chaoi is go</i>.", see:["le go mbeidh"] },
{ ga:"is minic a", en:"often, it is often that", cat:"gram",
  note:"A fronting construction: the adverb comes first, with <i>a</i> + lenition after it. Same shape in <i>is annamh a</i> (seldom), <i>is beag a</i> (little), <i>is fada a</i> (long).", see:["a mhinice agus is féidir"] },
{ ga:"Is é an rud a deir daoine ná…", en:"what people say is…", cat:"gram",
  note:"The <i>ná</i> is not “than” here — it links the two halves of an identifying sentence. <i>Is é an rud atá i gceist ná…</i> is the standard way to start an explanation." },
{ ga:"ní ‘teach’ a bheas agat ach ‘chack’", en:"it isn't ‘teach’ you'll have but ‘chack’", cat:"gram",
  note:"A cleft sentence: <i>ní X a… ach Y</i>. <b>A bheas</b> is the Ulster relative future (standard <i>a bheidh</i>); you'll see the same in <i>a bhíos</i> for <i>a bhíonn</i>.", noq:true },
{ ga:"bí le + ainm briathartha", en:"to intend to, to be going to", cat:"gram",
  note:"Ulster: <b>má tá muid leis an Ghaeilge a fhoghlaim</b> = if we're going to learn Irish. Object before <i>a</i> + lenited verbal noun. Verbs of motion take no <i>a</i>: <i>tá mé le dul</i>. Standard equivalent: <i>tá mé chun…</i>", see:["Le fáil","le cluinstin"] },
{ ga:"dá mbeadh scrúdú le déanamh agam", en:"if I had an exam to do", cat:"gram",
  note:"Two structures at once: <i>dá</i> + eclipsis + conditional for the unreal “if”, and <i>bí le</i> + verbal noun for the thing to be done.", see:["bí le + ainm briathartha"] },
{ ga:"Bhí sé ina sheasamh os mo chomhair", en:"he was standing in front of me", cat:"gram",
  note:"States of the body use <b>i + possessive + verbal noun</b>: <i>ina sheasamh</i> (standing), <i>ina shuí</i> (sitting), <i>ina luí</i> (lying), <i>ina chodladh</i> (asleep). <i>Os comhair</i> = in front of, facing." },
{ ga:"cuir i gcás", en:"take the case of, for instance", cat:"gram",
  note:"An imperative used as a discourse marker, like “say” or “suppose” in English. <i>Cuir i gcás go…</i> = suppose that…" },
{ ga:"Má fhéadaim obair a fháil", en:"if I can get work", cat:"gram",
  note:"<i>Má</i> + lenition, with the ordinary present. <i>Féad</i> = be able to, a lighter alternative to <i>is féidir liom</i>.", see:["Féad"] },
{ ga:"a bhaineann leis an chaint", en:"relating to speech", cat:"gram",
  note:"<i>Bain le</i> = to concern, to relate to — one of the most useful relative tags in essay writing: <i>na rudaí a bhaineann leis seo</i>." },
{ ga:"baineann sin truisle astu", en:"that trips them up", cat:"nath",
  note:"<i>Bain X as Y</i> = take X out of Y, hence “to get a stumble out of someone”. Ulster <i>truisle</i>; standard <i>tuisle</i>. The same frame gives <i>bain gáire as duine</i> (make someone laugh) and <i>bain úsáid as</i> (make use of)." },
{ ga:"cineál", en:"kind, sort; kind of", cat:"gram",
  note:"As a filler it works exactly like the English “kind of”. As a noun, <i>cineál</i> = a kind or type, from the same root as <i>cine</i> (race, kin).", see:["An cine daonna"] },
{ ga:"inar tógadh mé", en:"in which I was raised", cat:"gram",
  note:"Indirect relative with a preposition: <i>i</i> + <i>ar</i> (past) = <b>inar</b>. <i>Tógadh</i> is the autonomous past of <i>tóg</i>, which covers rearing, lifting and building. Douglas Hyde's poem <i>An Gleann inar Tógadh Mé</i> was a school text for generations." },
{ ga:"ina mbíonn", en:"in which (habitually) there is", cat:"gram",
  note:"<i>I</i> + relative <i>a</i> = <b>ina</b>, with eclipsis. Present <i>ina bhfuil</i>, past <i>inar</i>." },
{ ga:"i ngach aimsir", en:"in every tense", cat:"teanga",
  note:"<i>Aimsir</i> does triple duty: tense, time and weather. <i>An aimsir chaite</i> = the past tense; <i>an aimsir inniu</i> = today's weather." },
{ ga:"an chuid is mó", en:"most of, the greater part", cat:"gram",
  note:"<b>an chuid is mó de na daoine</b> = most people. Past tense: <i>an chuid ba mhó</i>. The related <i>den chuid is mó</i> = for the most part." },
{ ga:"a thabharfadh ar X Y a dhéanamh", en:"that would make X do Y", cat:"gram",
  note:"<b>tabhair ar dhuine rud a dhéanamh</b> = to make or compel someone to do something. Not the same as <i>tabhair do</i> (give to). <i>Thug sé orm fanacht</i> = he made me wait." },
{ ga:"caith le", en:"to treat (in a certain way)", cat:"gram",
  note:"<i>Caith</i> is a workhorse: throw, spend, wear, smoke — and with <i>le</i>, to treat. <b>Caitheadh go holc leo</b> = they were treated badly." },
{ ga:"Mórán", en:"much, many", cat:"gram",
  note:"Mostly negative or interrogative: <i>níl mórán ann</i>, <i>an bhfuil mórán le déanamh?</i> In the positive you'd say <i>cuid mhór</i> or <i>go leor</i>.", see:["cuid mhór"] },
{ ga:"An iomarca", en:"too much, too many", cat:"gram",
  note:"Standard; Ulster prefers <b>barraíocht</b>. Both take <i>de</i>: <i>an iomarca de sin</i>." },
{ ga:"Pé", en:"whoever, whatever, whichever", cat:"gram", see:["Pé hé féin","cibé rud atá againn"] },
{ ga:"Pé hé féin", en:"whoever he is", cat:"gram",
  note:"<i>Pé</i> prefixes <i>h</i> to the pronoun. Also <b>pé scéal é</b> = anyway, in any case — a very common way of changing the subject." },
{ ga:"agus muid ag deifriú", en:"while we were rushing", cat:"gram",
  note:"<b>agus</b> + pronoun + verbal noun = “while”, with no verb needed. <i>Agus mé óg</i> = when I was young. One of the most economical structures in the language.", see:["Deifir"] },
{ ga:"‘a’ na huilíochta", en:"the ‘a’ of totality — all that", cat:"gram",
  note:"A special relative <i>a</i> meaning “all that”, with eclipsis: <b>sin a dtuigim</b> = that's all I understand; <b>sin a ndeir sé</b> = that's all he says; <b>a bhfuil agam</b> = all that I have. In the past it combines with <i>de</i>: <i>dá bhfaca mé</i> = of all I ever saw.", see:["Sin a dtuigim"] },
{ ga:"Sin a dtuigim", en:"that's all I understand", cat:"gram", see:["‘a’ na huilíochta"] },

/* ============ TEANGEOLAÍOCHT ============ */
{ ga:"Dearcadh", en:"outlook, view, attitude", cat:"coláiste",
  note:"From <i>dearc</i>, to look. Watch the possessives: <i>a dhearcadh</i> (his, lenited), <i>a dearcadh</i> (her, unchanged), <i>a ndearcadh</i> (their, eclipsed).", see:["Dearc ort féin"] },
{ ga:"Cúrsa", en:"course; matter, affair", cat:"coláiste",
  note:"In the plural with a genitive it means “matters, affairs”: <i>cúrsaí polaitíochta</i>, <i>cúrsaí reatha</i> (current affairs), <i>cúrsaí féiniúlachta</i> (identity issues). Enormously useful for titling a topic." },
{ ga:"Dul cainte", en:"turn of phrase, idiom", cat:"teanga",
  note:"<i>Dul</i> here is “way, manner, construction” rather than “going”. <i>Tá dul deas ar an abairt sin</i> = that sentence is nicely turned." },
{ ga:"Gné", en:"aspect, form, species", cat:"coláiste",
  note:"<i>Gné den fhoghlaim</i> = an aspect of learning. In biology, a species; in grammar, verbal aspect." },
{ ga:"Cuirim beaguchtach ar dhuine", en:"I discourage someone", cat:"mothu",
  note:"<i>beag</i> + <i>uchtach</i> (courage, heart) — literally “little-heartedness”. Its opposite, <b>misneach a thabhairt do dhuine</b>, is to encourage them." },
{ ga:"Léar daoine", en:"a lot of people", cat:"beatha",
  note:"Ulster. Standard <i>a lán daoine</i> or <i>go leor daoine</i>." },
{ ga:"blas cainte", en:"accent", cat:"teanga",
  note:"Literally “the taste of speech”. <i>Blas</i> is also a taste in the mouth, and <i>tá blas maith ar a chuid Gaeilge</i> means his Irish sounds right — the metaphor runs both ways.", see:["tuin"] },
{ ga:"tuin", en:"intonation, tone, lilt", cat:"teanga",
  note:"<i>Tuin chainte</i> = intonation. Feminine, so the following words lenite: <i>an tuin chainte chéanna</i> — contrast masculine <i>an blas cainte céanna</i>.", see:["blas cainte"] },
{ ga:"Aithris", en:"to narrate, recite; to imitate", cat:"teanga",
  note:"Both senses matter: <i>aithris ar dhuine</i> is to mimic someone, <i>dán a aithris</i> is to recite a poem. <i>Aithriseoireacht</i> is recitation as a competition discipline at the Oireachtas." },
{ ga:"Amhras", en:"doubt, suspicion", cat:"tuairim",
  note:"<b>Tá amhras orm</b> = I have a doubt; <b>in amhras faoi</b> = suspicious of; <b>gan amhras</b> = without a doubt. <i>Amhrasach</i> = sceptical, or shady.", see:["gan amhras"] },
{ ga:"léiriú", en:"illustration, clarification; production", cat:"teanga",
  note:"Also a theatre or film production — <i>léiritheoir</i> is a producer or director.", see:["Léirigh"] },
{ ga:"Léirigh", en:"to clarify, illustrate, explain, show", cat:"focail", see:["léiriú"] },
{ ga:"taifeadadh", en:"a recording", cat:"teanga",
  note:"Plural <i>taifeadtaí</i>. The great example is the Doegen Records — Irish dialect recordings made for the Royal Irish Academy, with the Ulster sessions at Queen's in September 1931 and Letterkenny that October. Many of those dialects are now extinct; you can hear them free at doegen.ie.", see:["Taifigh"] },
{ ga:"Taifigh", en:"to analyse, resolve", cat:"focail",
  note:"Easily confused with <i>taifead</i> (to record) — different words, one letter apart.", see:["taifeadadh"] },
{ ga:"Fuaimnigh", en:"to pronounce, to sound", cat:"teanga", see:["Foghar","défhoghar"] },
{ ga:"Foghar", en:"a sound (of speech)", cat:"teanga",
  note:"The root behind <i>foghraíocht</i> (phonetics) and <i>défhoghar</i> (diphthong). Not the same word as <i>fuaim</i>, which is sound in general.", see:["défhoghar"] },
{ ga:"défhoghar", en:"diphthong", cat:"teanga",
  note:"<i>dé-</i> (two) + <i>foghar</i> (sound). Antain's point: <i>siad</i> has no síneadh fada but is long anyway, because <i>ia</i> is a diphthong." },
{ ga:"guta / consan", en:"vowel / consonant", cat:"teanga",
  note:"The core distinction in Irish spelling: <i>caol le caol agus leathan le leathan</i> — the vowels on either side of a consonant must match in quality, and that tells you whether the consonant is slender or broad." },
{ ga:"Síneadh", en:"a stretch, an extension", cat:"teanga",
  note:"This is why the accent is called a <b>síneadh fada</b> — a “long stretch”. Straight from <i>sín</i>, to stretch. Knowing that makes the term stop being arbitrary.", see:["sín / shín mé"] },
{ ga:"sín / shín mé", en:"to stretch / I stretched", cat:"focail", see:["Síneadh"] },
{ ga:"an t-alt", en:"the definite article", cat:"teanga",
  note:"<i>Alt</i> also means a joint, a paragraph, and an article in a newspaper or an act of law — a cluster of “sections, jointed things”." },
{ ga:"ní i gcónaí a chluintear é", en:"it isn't always heard", cat:"teanga",
  note:"Fronted negative: <i>ní</i> + the adverb + <i>a</i> + verb. <i>Chluintear</i> is the Ulster autonomous present of <i>cluin</i>; standard <i>cloistear</i>.", see:["le cluinstin"] },
{ ga:"le cluinstin", en:"to be heard, audible", cat:"gram",
  note:"<i>Bí le</i> + verbal noun again, in its passive sense. Same shape: <i>le fáil</i> (to be had), <i>le feiceáil</i> (to be seen), <i>le déanamh</i> (to be done).", see:["Le fáil","bí le + ainm briathartha"] },
{ ga:"Le fáil", en:"available, to be had", cat:"gram", see:["le cluinstin"] },
{ ga:"caighdeánach", en:"standard", cat:"teanga",
  note:"<i>An Caighdeán Oifigiúil</i>, first published in 1958, was drawn up to give the civil service and schools one written form. It is a compromise across the three dialects, which is exactly why Ulster speech so often departs from it." },
{ ga:"logainmníocht", en:"the study of place-names", cat:"teanga",
  note:"<i>log</i> (place, hollow) + <i>ainm</i> (name). The State database is at logainm.ie. The discipline matters here because anglicised names froze Irish pronunciation at the moment the mapmakers heard it.", see:["Léim an Mhadaidh","Port an Pheire"] },
{ ga:"cé chomh bunúsach is atá sé", en:"how basic it is", cat:"gram",
  note:"<b>cé chomh + adjective + is atá</b>. Also <i>cé chomh fada is a bheidh tú?</i> = how long will you be?" },
{ ga:"bunúsach", en:"basic, fundamental", cat:"focail",
  note:"From <i>bun</i> (base, bottom), a very productive root: <i>bunscoil</i> (primary school), <i>bunchéim</i> (positive degree; also a primary degree), <i>bunaigh</i> (to found), <i>ó bhun go barr</i> (from top to bottom).", see:["Bunaigh","Bunchéim"] },
{ ga:"an t-ainmní", en:"the subject (of a verb)", cat:"teanga",
  note:"From <i>ainm</i> (name). Its partner is <b>an cuspóir</b>, the object — which is the same word as “aim, objective”, so context decides.", see:["cur chuige"] },
{ ga:"mír (míreanna)", en:"item, segment, part", cat:"coláiste",
  note:"Used for a clip or item in a course: <i>Mír 5</i>. In grammar, <i>mír bhriathartha</i> = a verbal particle." },
{ ga:"ag toiseacht", en:"starting", cat:"gram",
  note:"Ulster <i>toisigh</i> for standard <i>tosaigh</i>; verbal noun <i>toiseacht</i> for <i>tosú</i>." },
{ ga:"le hainmneacha briathartha", en:"with verbal nouns", cat:"teanga",
  note:"<i>Le</i> prefixes <i>h</i> to a vowel. An <i>ainm briathartha</i> — ól, teacht, siúl — is the noun form of a verb, and Irish leans on it where English would use a participle or infinitive." },

/* ============ COLÁISTE ============ */
{ ga:"Deis", en:"opportunity; right-hand side; device", cat:"focail",
  note:"Three senses from one word. <i>Ar dheis</i> = on the right; <i>ar dheis Dé</i> = at God's right hand. <b>Deis a fháil</b> = to get a chance. And the geographical link: <i>deas</i> (right) gives <i>deisceart</i> (the south).", see:["Tuaisceart / Deisceart / Oirthear / Iarthar"] },
{ ga:"Riachtanach", en:"necessary, essential", cat:"coláiste",
  note:"<i>Riachtanas</i> = a requirement; <i>léitheoireacht riachtanach</i> = required reading; <i>riachtanais speisialta</i> = special needs." },
{ ga:"An Ardteistiméireacht", en:"the Leaving Certificate", cat:"coláiste",
  note:"Literally “the high testimonial”. It's the Southern school-leaving exam; Northern students sit A-levels instead, so the two jurisdictions have no shared term for the thing." },
{ ga:"cur chuige", en:"approach, way of going about it", cat:"coláiste",
  note:"From <b>cuir chuige</b> = set about it: <i>má chuireann tú chuige mar is ceart</i> = if you go about it properly. The noun is standard in essays: <i>cur chuige difriúil</i> = a different approach." },
{ ga:"an-dian", en:"very strict, very intense", cat:"coláiste",
  note:"<i>An-</i> lenites, except before d, s, t: <i>an-mhaith</i> but <i>an-dian</i>, <i>an-sásta</i>, <i>an-te</i>." },
{ ga:"Tá sé de ghlanmheabhair agam", en:"I have it off by heart", cat:"nath",
  note:"<i>glan</i> (clean) + <i>meabhair</i> (memory, mind) — a clean memory, nothing left on the page. Irish uses memory where English uses the heart.", see:["Meabhair"] },
{ ga:"Meabhair", en:"memory, mind, sense", cat:"focail",
  note:"<b>Is meabhair liom go…</b> = I recollect that…; <b>tá meabhair mhaith agam air</b> = I remember it well; <i>meabhrach</i> = intelligent; <i>as mo mheabhair</i> = out of my mind.", see:["Tá sé de ghlanmheabhair agam","Ciall"] },
{ ga:"A bheith in ann iad a spreagadh", en:"to be able to encourage them", cat:"gram",
  note:"<b>Bí in ann</b> + object + <i>a</i> + lenited verbal noun = to be able to do something. Ulster also uses <i>bí ábalta</i> and <i>tig le</i>." },
{ ga:"mná rialta", en:"nuns", cat:"focail",
  note:"A <i>bean rialta</i> is literally a “regular woman” — a woman living under a monastic <i>riail</i>, a rule. Exactly the same logic as English “regular clergy”.", see:["Riail","rialta"] },
{ ga:"Riail", en:"a rule", cat:"focail",
  note:"From Latin <i>regula</i>. Gives <i>rialta</i> (regular), <i>rialaigh</i> (to rule, regulate), <i>rialtas</i> (government) and <i>rialtóir</i> (ruler — both kinds).", see:["rialta","Rialaigh"] },
{ ga:"rialta", en:"regular; religious (of orders)", cat:"focail", see:["Riail","mná rialta"] },
{ ga:"Rialaigh", en:"to rule, to regulate", cat:"focail", see:["Riail"] },
{ ga:"Bunchéim", en:"positive degree (of an adjective)", cat:"teanga",
  note:"The three degrees: <b>bunchéim</b> (maith), <b>breischéim</b> (níos fearr), <b>sárchéim</b> (is fearr). <i>Bun</i> = base, <i>breis</i> = increase, <i>sár</i> = surpassing.", see:["Breischéim","Sárchéim"] },
{ ga:"Breischéim", en:"comparative degree", cat:"teanga",
  note:"<b>níos</b> is a worn-down <i>ní is</i> — “the thing that is”. In the past it becomes <b>ní ba</b> (+ lenition): <i>ní ba dheacra</i>. Knowing the origin explains why the past form looks so odd.", see:["Bunchéim","Sárchéim"] },
{ ga:"Sárchéim", en:"superlative degree", cat:"teanga",
  note:"<i>sár-</i> = surpassing, the same prefix as <i>sárobair</i> (excellent work) and the verb <i>sáraigh</i>. Present <b>is</b>, past <b>ba</b> (+ lenition), and <b>ab</b> before a vowel or fh: <i>ab fhearr, ab óige</i>.", see:["Sáraigh","Bunchéim"] },

/* ============ COMPARISON EXAMPLES ============ */
{ ga:"Is fearr tusa ná mise", en:"you are better than me", cat:"gram",
  note:"Copula comparison. The same thought with <i>tá</i>: <b>Tá tusa níos fearr ná mise</b>. The copula version is tighter and more emphatic.", noq:true },
{ ga:"Tá an rang seo níos dúshlánaí ná rang Airt", en:"this class is more challenging than Art", cat:"gram",
  note:"With the copula: <b>Is dúshlánaí an rang seo ná rang Airt</b>. Note <i>ná</i>, not <i>na</i>.", noq:true },
{ ga:"Bhí an rang sin ní ba dheacra ná rang Airt", en:"that class was harder than Art", cat:"gram",
  note:"Past comparative: <b>ní ba</b> + lenition. With the copula: <b>Ba dheacra an rang sin ná rang Airt</b>.", noq:true },
{ ga:"Is é seo an rang is deacra", en:"this is the hardest class", cat:"gram",
  note:"Past: <b>Ba é sin an rang ba dheacra</b>. The superlative needs the article plus <i>is</i>/<i>ba</i>.", noq:true },
{ ga:"Is eisean an duine is óige", en:"he is the youngest person", cat:"gram",
  note:"Past: <b>Ba eisean an duine ab óige</b> — <i>ab</i> before a vowel.", noq:true },
{ ga:"Sin rang ar fhreastail mé air", en:"that's a class I attended", cat:"gram",
  note:"Indirect relative, because a preposition is involved: <i>freastail ar</i>. Past indirect = <b>ar</b> + lenition, with the preposition picked up again at the end (<i>air</i>).", noq:true },
{ ga:"Sin an scannán ba mheasa dá bhfaca mé", en:"that's the worst film I ever saw", cat:"gram",
  note:"<b>dá</b> here is <i>de</i> + the ‘a’ of totality — “of all that”. <i>Dár casadh orm riamh</i>, <i>dá bhfaca mé</i>, <i>dá raibh ann</i>.", see:["‘a’ na huilíochta"], noq:true },
{ ga:"tá sé ar an fhear is láidre", en:"he is the strongest man", cat:"gram",
  note:"Ulster uses <b>bí ar</b> to rank: <i>tá sé ar an fhear is láidre</i>. For “one of”, <b>ar dhuine de</b>: <i>tá sí ar dhuine de na daoine is cliste</i>. <i>Ar</i> lenites, hence <i>dhuine</i>." },

/* ============ CEISTEANNA — DAFTA ============ */
{ ga:"Cén dóigh", en:"how, in what way", cat:"gram",
  note:"Ulster <i>dóigh</i>, Connacht <i>caoi</i> (<i>cén chaoi</i>), Munster/standard <i>conas</i>. Part of the DAFTA set — see the Nótaí tab." },
{ ga:"Cén áit", en:"where, what place", cat:"gram" },
{ ga:"Cén fáth", en:"why, what reason", cat:"gram",
  note:"Ulster also <b>cad chuige</b>. Takes the indirect relative: <i>cén fáth a ndearna tú é?</i>", see:["Cén fáth a ndearna tú?"] },
{ ga:"Cén treo", en:"which direction", cat:"gram" },
{ ga:"Cén t-am", en:"what time", cat:"gram",
  note:"The one in the DAFTA set that wobbles: you'll also meet the direct relative with time words — <i>cén t-am a bheas an rang thart?</i>, <i>an uair a thuig mé</i>. Both are heard." },
{ ga:"Cén fáth a ndearna tú?", en:"why did you do it?", cat:"gram",
  note:"Indirect relative + eclipsis, and <i>dearna</i> is the dependent past of <i>déan</i>. Compare the direct: <i>an rud a rinne tú</i>." },

/* ============ BRIATHRA GLUAISEACHTA ============ */
{ ga:"Chuaigh mé a shiopadóireacht", en:"I went shopping", cat:"gram",
  note:"After a verb of motion, Ulster uses <b>a</b> + lenited verbal noun where the standard often has <i>ag</i>: <i>chuaigh mé ag siopadóireacht</i>. The <i>a</i> is a worn-down <i>do</i>, and the pattern is the older one.", see:["Tháinig mé anseo a fhoghlaim Gaeilge"] },
{ ga:"Tháinig mé anseo a fhoghlaim Gaeilge", en:"I came here to learn Irish", cat:"gram", see:["Chuaigh mé a shiopadóireacht"] },
{ ga:"D’imigh sé a thógáil tí", en:"he went off to build a house", cat:"gram",
  note:"Note the genitive after the verbal noun: <i>tógáil tí</i>, building of a house." },
{ ga:"Thosaigh sé a chur ceiste", en:"he began to ask a question", cat:"gram",
  note:"<i>Ceist a chur</i> = to ask a question; in the genitive after the verbal noun it becomes <i>ceiste</i>." },
{ ga:"Tá mé ag gabháil do do phógadh", en:"I'm going to kiss you", cat:"gram",
  note:"Ulster <b>ag gabháil</b> = going (standard <i>ag dul</i>). Two <i>do</i>s here and both are needed: the first is the particle, the second is “your”. The sheet drops one." },

/* ============ STAIR IS POLAITÍOCHT ============ */
{ ga:"An Ghaill", en:"Gaul", cat:"stair",
  note:"The lecture's contrast was Celtic Gaul against <b>Impireacht na Róimhe</b>, the Roman Empire. The word <i>Gall</i> originally meant a Gaul, then came to mean any foreigner — first the Norse, later the Anglo-Normans and English. That drift is why you get <i>Dubhghaill</i> and <i>Fionnghaill</i> (dark and fair foreigners, i.e. Danes and Norwegians), which survive in the surname Ó Dubhghaill (Doyle) and the place-name Fine Gall (Fingal).", see:["Fine","Na Lochlannaigh"] },
{ ga:"Henri d’Arbois de Jubainville", en:"French Celticist (1827–1910)", cat:"stair",
  note:"Held the first chair of Celtic at the Collège de France from 1882. He argued for a direct line between the religion and institutions of Celtic Gaul and what survives in early Irish literature — which is why he turns up in a lecture comparing Gaul and Rome. His <i>Le cycle mythologique irlandais</i> shaped how the Irish sagas were read for a generation.", noq:true },
{ ga:"An Chríostaíocht → litríocht na Sean-Ghaeilge", en:"Christianity (5th c.) → Old Irish literature", cat:"stair",
  note:"Christianity brought the Latin alphabet, and with it monastic scribes. Irish ends up with the oldest vernacular literature in Western Europe after Greek and Latin — not because the Irish were unusually literary, but because monks wrote the vernacular down instead of only Latin.", noq:true },
{ ga:"Na Lochlannaigh", en:"the Vikings, the Norse (9th c.)", cat:"stair",
  note:"From <i>Lochlann</i>, the Irish name for Scandinavia. First raids from 795; Dublin founded as a longphort in 841. They gave Irish a layer of sea and trade vocabulary — <i>bád</i> (boat), <i>margadh</i> (market), <i>pingin</i> (penny) — and most of the coastal town names on the east coast.", see:["An Ghaill"] },
{ ga:"Na hAngla-Normannaigh", en:"the Anglo-Normans (12th c.)", cat:"stair",
  note:"Landed 1169. Within a few generations many families were <i>Gaelacha</i> in speech and law — the origin of the phrase “more Irish than the Irish themselves”. The Statutes of Kilkenny (1366) were an attempt to stop exactly that.", noq:true },
{ ga:"Plandáil Uladh", en:"the Plantation of Ulster", cat:"stair",
  note:"Worth correcting on the sheet: the Plantation is <b>17th century</b> — from 1609, after the Flight of the Earls in 1607 — not the 19th. The 19th century is the century of the real collapse in Irish speaking: the Famine, mass emigration and the National Schools.", noq:true },
{ ga:"Labhairt na Gaeilge i measc na mbochtán", en:"the speaking of Irish among the poor", cat:"stair",
  note:"The 19th-century pattern: Irish survived longest where there was least money, and the language became associated with poverty — which is precisely the association the Revival set out to break.", noq:true },
{ ga:"An cine daonna", en:"the human race", cat:"stair",
  note:"<i>Cine</i> = race, kin-group; <i>daonna</i> = human, from <i>duine</i>. Related: <i>daonlathas</i> (democracy, “people-rule”) and <i>daonra</i> (population).", see:["Fine","is olc an rud cúl le cine"] },
{ ga:"is olc an rud cúl le cine", en:"it's a bad thing to turn your back on your own kin", cat:"nath",
  note:"<i>Cúl le cine</i> — back to the kin — is an old charge, levelled at anyone thought to have abandoned their own people or language.", see:["droim láimhe a thabhairt do"] },
{ ga:"droim láimhe a thabhairt do", en:"to reject, to turn one's back on", cat:"nath",
  note:"Literally “to give the back of the hand to”. A dismissal, not a blow.", see:["is olc an rud cúl le cine"] },
{ ga:"Fiann", en:"a band of warriors", cat:"stair",
  note:"Plural <i>Fianna</i> — the roving war-bands of the Fenian Cycle, Fionn Mac Cumhaill's men. The name was revived in the 19th century by the Fenians and again by <b>Fianna Fáil</b>, “Warriors of Fál” (Fál being an old name for Ireland).", see:["Fine"] },
{ ga:"Fine", en:"a tribe, a kin-group", cat:"stair",
  note:"In early Irish law the <i>fine</i> was the extended kin that held land jointly and answered for each other's debts — the basic legal unit. <b>Fine Gael</b> means “the kindred of the Irish”. Also <i>fine gheal</i> in genealogy.", see:["Fiann","An cine daonna"] },
{ ga:"An tOrd Oráisteach", en:"the Orange Order", cat:"stair",
  note:"Founded in 1795 near Loughgall, Co. Armagh, after the Battle of the Diamond, and named for William of Orange. <i>Ord</i> = an order, in both the religious and the sequential sense." },
{ ga:"Agóid", en:"a protest", cat:"stair",
  note:"<b>Agóid a dhéanamh in éadan ruda</b> = to protest against something. <i>Agóideoir</i> = protester.", see:["in éadan","cuir in éadan"] },
{ ga:"in éadan", en:"against", cat:"stair",
  note:"Ulster, where the standard often has <i>i gcoinne</i>. <i>Éadan</i> = forehead, face, front — also <i>in éadan an lae</i>, per day.", see:["cuir in éadan"] },
{ ga:"Ionsaí", en:"an attack", cat:"stair",
  note:"Verb <i>ionsaigh</i>. In older texts <i>ionsaí</i> can simply mean approaching someone — the hostile sense hardened over time." },
{ ga:"Tacaíocht", en:"support", cat:"stair",
  note:"From <i>taca</i>, a prop or support — the same word as in <i>i dtaca liomsa de</i> and <i>um an dtaca seo</i>.", see:["i dtaca liomsa de"] },
{ ga:"Gnáthshaol", en:"everyday life", cat:"beatha",
  note:"<i>gnáth-</i> (usual, ordinary) is productive: <i>gnáthdhuine</i> (ordinary person), <i>gnáthóg</i> (habitat), <i>de ghnáth</i> (usually)." },
{ ga:"An fód", en:"the sod, the ground", cat:"focail",
  note:"<b>Seasamh an fhóid</b> = to stand your ground; <i>fód dúchais</i> = native sod, where you're from. Turf is cut in <i>fóid</i>." },
{ ga:"Scriosta", en:"wrecked, exhausted", cat:"mothu",
  note:"Verbal adjective of <i>scrios</i>, to destroy. Used of people exactly as English uses “destroyed” or “wrecked” for tired out." },
{ ga:"Leas", en:"benefit, good, welfare", cat:"focail",
  note:"<i>Ar mhaithe le leas na ndaoine</i> = for the people's good. Its opposite <b>aimhleas</b> is harm, with the negative prefix <i>aimh-</i>. Also <i>leas sóisialta</i> = social welfare.", see:["aimhleas"] },
{ ga:"aimhleas", en:"harm, detriment", cat:"focail",
  note:"<i>Dul chun aimhleasa</i> = to go to the bad. The <i>aimh-</i> prefix also gives <i>aimhréidh</i> (tangled) from <i>réidh</i> (smooth).", see:["Leas"] },
{ ga:"dlúthchuid", en:"an integral part", cat:"tuairim",
  note:"<b>Is dlúthchuid den chultúr í an teanga</b> = the language is an integral part of the culture. Essay gold.", see:["I ndlúthpháirtíocht"] },
{ ga:"go smior", en:"to the marrow, through and through", cat:"nath",
  note:"<i>Smior</i> = marrow. <b>Gaeilgeoir go smior</b> = an Irish speaker to the bone. Pairs naturally with <i>fuath na n-ae</i> for bodily intensity.", see:["fuath na n-ae"] },
{ ga:"fud fad na cruinne", en:"throughout the whole world", cat:"nath",
  note:"<i>Ar fud</i> = throughout, <i>fad</i> = length, <i>an chruinne</i> = the globe. A doubled phrase for emphasis, like “the length and breadth”.", see:["Cruinne"] },
{ ga:"dual do", en:"natural to, in someone's nature", cat:"nath",
  note:"<b>Is dual dó é</b> = it's in his nature. Related to <i>dúchas</i> (heritage, native instinct) — hence <i>briseann an dúchas trí shúile an chait</i>, nature breaks out through the cat's eyes." },
{ ga:"scun scan", en:"completely, entirely", cat:"nath",
  note:"Ulster. A rhyming doublet of the same type as <i>riamh nó iaramh</i> — neither half means much alone.", see:["Riamh nó iaramh"] },
{ ga:"Acmhainneach", en:"resilient, resourceful, able to bear", cat:"focail",
  note:"From <i>acmhainn</i> = capacity, means, resources. <b>Níl acmhainn agam air</b> = I can't afford it, or I can't stand it. Written <i>achmhainneach</i> in Ulster." },
{ ga:"caith ar shiúl", en:"to throw away", cat:"focail",
  note:"Ulster, for standard <i>caith amach</i> / <i>caith uait</i>. <i>Ar shiúl</i> = away, gone — <i>tá sé ar shiúl</i> = he's away." },
{ ga:"bain amach", en:"to achieve, to win, to reach", cat:"focail",
  note:"<b>Céim a bhaint amach</b> = to get a degree; <b>an baile a bhaint amach</b> = to reach home. Another of the <i>bain</i> family: <i>bain úsáid as</i>, <i>bain triail as</i>, <i>bain sult as</i>.", see:["baineann sin truisle astu"] },
{ ga:"tiontaigh / iompaigh", en:"to turn", cat:"focail",
  note:"<i>Tiontaigh</i> also means to translate (to turn one language into another). <i>Iompaigh</i> is the more physical turn, and <i>iompú</i> can mean a religious conversion." },
{ ga:"os ard", en:"aloud, out loud", cat:"beatha",
  note:"<i>Os</i> = above, over: <i>os comhair</i> (in front of), <i>os cionn</i> (above), <i>os íseal</i> (quietly, in secret) — the exact opposite of <i>os ard</i>." },

/* ============ ÁITEANNA ============ */
{ ga:"Fána", en:"a downward slope", cat:"áit",
  note:"<b>Le fána</b> = downhill, literally and figuratively: <i>tá an gnó ag dul le fána</i>, the business is going downhill." },
{ ga:"siar / soir / ó dheas / ó thuaidh", en:"westward / eastward / southward / northward", cat:"áit",
  note:"Irish direction words carry motion in them. <i>Siar</i> = to the west, <b>aniar</b> = from the west; <i>soir</i> = to the east, <b>anoir</b> = from the east. So <i>gaoth aniar</i> is a west wind, blowing from the west.", see:["Siar is aniar","Tuaisceart / Deisceart / Oirthear / Iarthar"] },
{ ga:"Tuaisceart / Deisceart / Oirthear / Iarthar", en:"north / south / east / west (as regions)", cat:"áit",
  note:"These are built from a person facing the <i>rising sun</i>. East is in front (<i>oirthear</i>, from <i>oir</i>, front), west behind (<i>iarthar</i>, from <i>iar</i>, behind), south on the right (<i>deisceart</i>, from <i>deas</i>, right) and north on the left (<i>tuaisceart</i>, from <i>tuath</i>, left). The compass is a human body turned to the dawn.", see:["Deis"] },
{ ga:"Siar is aniar", en:"back and forward, to and fro", cat:"áit", see:["siar / soir / ó dheas / ó thuaidh"] },
{ ga:"Loch Garman", en:"Wexford", cat:"áit",
  note:"The Irish name comes from the legend of Garman, drowned in the loch. The English name is Norse — <i>Veisafjǫrðr</i>, the inlet of the mudflats — so the two names have nothing to do with each other." },
{ ga:"Ceatharlach", en:"Carlow", cat:"áit",
  note:"Usually read as <i>ceathar</i> + <i>loch</i>, “four lakes”, though scholars argue about it. There are no four lakes there now." },
{ ga:"An Ísiltír", en:"the Netherlands", cat:"áit",
  note:"<i>íseal</i> (low) + <i>tír</i> (land) — a straight calque of “Nether-lands”, the same construction in both languages." },
{ ga:"Léim an Mhadaidh", en:"Limavady", cat:"áit",
  note:"“The dog's leap” — from a legend of a hound leaping the Roe gorge carrying a message. Antain's point about the article: nobody says the <i>n</i>, and the anglicised spelling froze that — <b>Léim a' Mhadaidh</b> → Limavady. <i>Madadh</i> is Ulster for <i>madra</i>; genitive <i>madaidh</i>.", see:["Port an Pheire","logainmníocht"] },
{ ga:"Port an Pheire", en:"Portaferry", cat:"áit",
  note:"The landing place of the ferry. The same vanished article shows in Portadown (<i>Port an Dúnáin</i>) — these spellings are evidence of how Irish was pronounced when the mapmakers were listening.", see:["Léim an Mhadaidh"] },
{ ga:"Cruinne", en:"the globe, the universe; roundness", cat:"focail",
  note:"From <i>cruinn</i> = round, exact. The world is named for its shape. <i>Cruinnigh</i> = to gather (to make round), <i>cruinniú</i> = a meeting.", see:["fud fad na cruinne"] },

/* ============ FOCAIL BHUNÚSACHA ============ */
{ ga:"Cógas", en:"medication", cat:"focail",
  note:"<i>Cógaslann</i> = pharmacy; <i>cógaseolaíocht</i> = pharmacology. The <i>-lann</i> suffix makes places: <i>bialann</i>, <i>leabharlann</i>, <i>amharclann</i>." },
{ ga:"Draíochtach", en:"magical", cat:"focail",
  note:"<i>Draoi</i> = druid → <i>draíocht</i> = magic, enchantment → <i>draíochtach</i>. The druids left their name on the word for magic itself.", see:["Cealg"] },
{ ga:"Sáraigh", en:"to violate; to surpass, overcome", cat:"focail",
  note:"Both directions from <i>sár</i> (surpassing): to go beyond a limit, in the good sense (<i>sáraigh an curiarracht</i>, break the record) or the bad (<i>sárú cóipchirt</i>, copyright infringement). It carries a formal, legal register — the sheet's <i>sárú mná</i> is the older legal term for rape.", see:["Tá a shárú sin de scéal agam","Sárchéim"] },
{ ga:"Tá a shárú sin de scéal agam", en:"I have an even better story than that", cat:"nath",
  note:"Literally “I have the surpassing of that of a story”. A pub phrase — the Irish for “hold my pint”.", see:["Sáraigh"] },
{ ga:"Breathnaigh", en:"to observe, examine, look at", cat:"focail",
  note:"The everyday “look” in Connacht; Ulster says <i>amharc ar</i>, Munster <i>féach ar</i>. Three dialects, three different verbs for the most ordinary action there is.", see:["An tír a bhreathnú"] },
{ ga:"Ga (gathanna)", en:"a spear, dart, ray", cat:"focail",
  note:"<i>Ga gréine</i> = a sunbeam; <i>ga X</i> = an X-ray; <i>ga ciorcail</i> = the radius of a circle (the spoke of the wheel).", see:["Tá a gha ionam"] },
{ ga:"Tá a gha ionam", en:"he has it in for me", cat:"nath",
  note:"Literally “his dart is in me”.", see:["Ga (gathanna)"] },
{ ga:"Lonraigh", en:"to shine", cat:"focail",
  note:"<b>Lonrú ar rud</b> = to shine on something. <i>Lonrach</i> = shining, radiant." },
{ ga:"Bunaigh", en:"to found, establish", cat:"focail",
  note:"From <i>bun</i> (base). <i>Bunaíodh Conradh na Gaeilge i 1893</i> — the autonomous past is how you say an organisation “was founded”.", see:["bunúsach"] },
{ ga:"Aistriúchán", en:"a translation", cat:"teanga",
  note:"From <i>aistrigh</i> = to move, shift, transfer. Translation as carrying-across is the same image as Latin <i>translatio</i> and German <i>Übersetzung</i>. <i>Aistriú</i> can also mean moving house." },
{ ga:"Lonnaigh", en:"to settle, to stay", cat:"focail",
  note:"<b>Lonnú in áit</b> = to settle down in a place. A separate sense, from <i>lonn</i> (fierce): <b>lonnaigh faoi</b> = to become angry about." },
{ ga:"Um", en:"about, at (old preposition)", cat:"gram",
  note:"Largely dead, but it survives in set phrases: <i>um Nollaig</i> (at Christmas), <i>um thráthnóna</i> (in the evening), <i>um an dtaca seo</i> (by now), and the greeting <i>cad é mar atá tú um an am seo?</i>", see:["um an dtaca seo"] },
{ ga:"Bog", en:"soft; to soften, to move", cat:"focail",
  note:"Adjective and verb. <b>Bog leat</b> = off you go. In linguistics, <i>consan bog</i>; in computing, <i>bogearraí</i> = software — literally “soft goods”, a calque." },
{ ga:"Craobh", en:"a branch", cat:"focail",
  note:"A branch of a tree, a branch of an organisation (a <i>craobh</i> of Conradh na Gaeilge) — and a championship. <i>Craobh na hÉireann</i> is the All-Ireland, from the old sense of a branch or garland given to a champion." },
{ ga:"Cothaigh", en:"to feed, nourish, sustain", cat:"focail",
  note:"<i>Cothú</i> = nutrition; <i>cothrom</i> = level, fair; <i>cothrom na Féinne</i> = fair play, literally the Fianna's fair treatment of an opponent.", see:["Fiann"] },
{ ga:"Mol", en:"to praise, to recommend", cat:"focail",
  note:"The textbook verb of the first conjugation — every grammar table in the language runs <i>molaim, mholfainn, moltar</i>. Also the proverb <b>mol an óige agus tiocfaidh sí</b>, praise the young and they will flourish.", see:["molaim go bun na spéire é"] },
{ ga:"Féad", en:"to be able to", cat:"focail",
  note:"<i>Féadaim</i>, <i>d'fhéadfainn</i>. Lighter than <i>is féidir liom</i> and common in the conditional: <i>d'fhéadfá a rá</i> = you could say." },
{ ga:"Roghnaigh", en:"to choose, select", cat:"focail",
  note:"<i>Rogha</i> = a choice. <b>Níl an dara rogha agam</b> = I have no other choice." },
{ ga:"Gar", en:"nearness; a favour", cat:"focail",
  note:"<b>Is mór an gar go…</b> = it's lucky that…; <b>gar a dhéanamh do dhuine</b> = to do someone a favour; <b>i ngar do</b> = near to. Nearness and kindness in one word.", see:["tá sé i ngar duit go leor"] },
{ ga:"Cuidigh / cúnaigh", en:"to help", cat:"focail",
  note:"Ulster <i>cuidigh le</i>; standard also <i>cabhraigh le</i>. The noun <i>cúnamh</i> = help, and <i>lámh chúnta</i> = a helping hand.", see:["chun cabhrú liom"] },
{ ga:"Dearbhán", en:"a voucher", cat:"focail", see:["Dearbhaigh"] },
{ ga:"Dearbhaigh", en:"to confirm, declare, prove", cat:"focail",
  note:"<i>Dearbh</i> = certain, true. <i>Dearbhú</i> = a declaration; <i>dearbhán</i> = a voucher, i.e. a confirmation on paper.", see:["Dearbhán"] },
{ ga:"Muineál", en:"neck", cat:"focail",
  note:"<b>Muineál a chur ort féin</b> = to brazen it out. Genitive <i>muiníl</i>." },
{ ga:"Díth anála", en:"breathlessness", cat:"focail",
  note:"<i>Díth</i> = lack, want — the same word as in Ulster <b>de dhíth orm</b> (needed by me). <i>Anáil</i> = breath.", see:["Leas"] },
{ ga:"Sruthán", en:"a stream", cat:"áit",
  note:"Diminutive of <i>sruth</i> (a current). The <i>-án</i> suffix makes small things: <i>cnocán</i> (hillock), <i>leabhrán</i> (booklet), <i>gearrán</i>." },
{ ga:"Seal", en:"a turn, a while, a spell", cat:"am",
  note:"<b>Seal… seal…</b> = sometimes… sometimes…, alternating. <b>Glac sealanna</b> = take turns. <b>Seal oibre</b> = a shift." },
{ ga:"Braith / ag brath ar", en:"to perceive, feel; to depend on", cat:"focail",
  note:"Two senses: <i>bhraith mé uaim é</i> = I missed it; <i>ag brath ar</i> = depending on. Also <i>braiteoir</i> = a sensor." },
{ ga:"contúirt", en:"danger", cat:"focail",
  note:"Feminine: <i>an chontúirt</i>. <i>Contúirteach</i> = dangerous; <i>i mbaol</i> is the near-synonym for being at risk." },
{ ga:"Lorg crúb", en:"a hoofprint, a track", cat:"focail",
  note:"<i>Lorg</i> = a track or trace, and as a verb, to seek. <i>Ar lorg ruda</i> = looking for something. <i>Crúb</i> = a hoof or claw." },
{ ga:"An rud is deise", en:"the nearest thing", cat:"focail",
  note:"A trap: here <i>deas</i> means <b>near</b>, not “nice” — an Ulster sense. <i>An rud is deise don fhuaim Ghaeilge</i> = the nearest thing to the Irish sound. Standard would use <i>is gaire</i>." },
{ ga:"tá sé chomh maith agam", en:"I might as well", cat:"nath",
  note:"<b>Tá sé chomh maith agam imeacht</b> = I might as well go. With <i>againn</i>, <i>agat</i> and so on for other people." },
{ ga:"Ciall", en:"sense, meaning, sanity", cat:"focail",
  note:"<b>Ciall cheannaithe</b> = sense bought the hard way, wisdom from experience. <b>Cad is ciall leis?</b> = what does it mean? <b>Ciall a bhaint as</b> = to make sense of.", see:["Meabhair"] },
{ ga:"Áirithe", en:"certain, particular", cat:"focail",
  note:"<i>Rud áirithe</i> = a certain thing. The family: <b>go háirithe</b> (especially), <b>in áirithe</b> (reserved), <b>áireamh</b> (counting). All about singling things out.", see:["in áirithe","go háirid / go háirithe"] },
{ ga:"go háirid / go háirithe", en:"especially", cat:"gram",
  note:"Ulster <i>go háirid</i>; standard <i>go háirithe</i>.", see:["Áirithe"] },
{ ga:"Fuaigh", en:"to sew", cat:"focail",
  note:"Worth separating from the look-alikes: <i>fuaim</i> (sound), <i>fuaigh</i> (sew), <i>fuath</i> (hatred), <i>fuar</i> (cold). Four very different words within one letter of each other." },
{ ga:"cuid mhór", en:"a lot, a great deal", cat:"gram",
  note:"Ulster, for standard <i>a lán</i> / <i>go leor</i>. <i>Cuid</i> is feminine, so the adjective lenites: <i>cuid mhór</i>.", see:["Mórán"] },
{ ga:"Dán", en:"a poem; a gift, an art; destiny", cat:"focail",
  note:"The two meanings are worth holding together: a <i>dán</i> is both a poem and what is fated for you — <b>i ndán do</b> = in store for. The poet's art and the shape of a life were the same word.", see:["inar tógadh mé"] },
{ ga:"Maraigh", en:"to kill", cat:"focail",
  note:"Verbal noun <i>marú</i>. Also figurative: <i>tá mé maraithe ag an obair</i> = the work has me killed.", see:["Ag marú"] },
{ ga:"Ag marú", en:"killing", cat:"focail", see:["Maraigh"] },
{ ga:"Scaoil", en:"to loosen, release, untie; to fire (a shot)", cat:"focail",
  note:"<b>Scaoil leis</b> = let him go, or let it be. <i>Scaoilte</i> = loose, relaxed.", see:["comhrá scaoilte"] },
{ ga:"Aoi (aíonna)", en:"a guest", cat:"focail",
  note:"<i>Teach aíochta</i> = a guesthouse; <i>aoi-léachtóir</i> = a guest lecturer. The sheet also notes <i>ar aoi</i> = in regard to, a much rarer use." },
{ ga:"Cealg", en:"deceit, treachery; a sting", cat:"focail",
  note:"<i>Cealgaim</i> = I deceive. Also a bee's sting, and <i>cealgaire</i> = a deceiver. A cognate chain of “pricking” and “beguiling”." },
{ ga:"Furasta", en:"easy", cat:"focail",
  note:"Comparative is irregular: <b>fusa</b>. <i>Is fusa a rá ná a dhéanamh</i> = easier said than done. Spoken Ulster often shortens it to <i>furast'</i>.", see:["tá sé doiligh"] },
{ ga:"Gan dabht", en:"no doubt, certainly", cat:"tuairim",
  note:"A borrowing from English “doubt”, fully naturalised. The native equivalent is <i>gan amhras</i>.", see:["gan amhras"] },
{ ga:"ní miste", en:"it's no harm, no bother", cat:"nath",
  note:"Past and conditional <b>níor mhiste</b>. <b>Níor mhiste a rá go…</b> = it might be no harm to say that… — a very useful soft opener. Also <i>ní miste liom</i> = I don't mind.", see:["Níor mhiste a rá go…"] },
{ ga:"Níor mhiste a rá go…", en:"it might be no harm to say that…", cat:"tuairim", see:["ní miste"] },
{ ga:"ag urnaí", en:"praying", cat:"focail",
  note:"<i>Urnaí</i> = prayer. One of Antain's examples where the <i>g</i> of <i>ag</i> is heard, because a vowel follows." },
{ ga:"corr", en:"odd, occasional", cat:"gram", see:["corruair","corrdhuine"] },
{ ga:"corrdhuine", en:"the odd person, an occasional person", cat:"beatha", see:["corr","corruair"] },
{ ga:"Deifir", en:"hurry", cat:"mothu",
  note:"<b>Tá deifir orm</b> = I'm in a hurry; <b>ag deifriú</b> = rushing. Ulster also uses <i>dlús</i> and <i>broid</i>.", see:["agus muid ag deifriú"] },
{ ga:"b’éigean dom", en:"I had to", cat:"gram",
  note:"Present <b>is éigean dom</b>, future <b>beidh orm</b>, negative <b>níorbh éigean dom</b>. <i>Éigean</i> = compulsion, force — the same root as <i>ar éigean</i> (barely) and <i>foréigean</i> (violence). It is <b>not</b> <i>ainm</i>, though it sounds a bit like it at speed.", see:["Tá/Bhí mé in ainm a bheith ag obair"] },
{ ga:"Is éigean dom imeacht", en:"I have to go", cat:"gram", see:["b’éigean dom"] },
{ ga:"Tá/Bhí mé in ainm a bheith ag obair", en:"I am / was meant to be working", cat:"nath",
  note:"Literally “in name to be”. It carries the hint that the thing isn't actually happening: <i>bhí sé in ainm a bheith ina shaineolaí</i> = he was supposed to be an expert. Different from <i>b'éigean dom</i> (real compulsion) and <i>bhí orm</i> (I had to).", see:["b’éigean dom"] },

/* ============ SEANFHOCAIL ============ */
{ ga:"Folaíonn grá gráin", en:"love conceals ugliness — love is blind", cat:"nath",
  note:"The Ulster version the sheet is reaching for runs on: <b>…agus tchí fuath a lán</b> — “and hatred sees plenty”. The pair works because <i>gráin</i> means both ugliness and loathing. Worth checking the second half with your lecturer; the sheet's spelling is garbled.", see:["Gráin"], noq:true },
{ ga:"Tús maith leath na hoibre", en:"a good start is half the work", cat:"nath",
  note:"No verb in the sentence at all — proverbs often drop the copula entirely. <i>Obair</i> → genitive <i>na hoibre</i>, with <i>h</i> after <i>na</i>." },
{ ga:"Bailíonn brobh beart", en:"wisps gather to make a bundle — every little helps", cat:"nath",
  note:"<i>Brobh</i> = a wisp or blade of grass; <i>beart</i> = a bundle. Alliteration is doing the memory work, as in most Irish proverbs." },
{ ga:"Is fearr Gaeilge bhriste ná Béarla cliste", en:"broken Irish is better than clever English", cat:"nath",
  note:"The slogan of every Gaeltacht summer college. The counter-argument to anyone too self-conscious to open their mouth." },

/* ============ BREIS ============ */
{ ga:"ar bun", en:"under way, in operation", cat:"beatha",
  note:"<b>Tá rang ar bun</b> = a class is on. Close neighbour of <i>ar siúl</i>, and both build a state out of <i>ar</i> + a bare noun.", see:["ar siúl"] },
{ ga:"tá cuma thuirseach air", en:"he looks tired", cat:"mothu",
  note:"<b>Tá cuma X ar dhuine</b> = someone looks X. <i>Cuma</i> is feminine, so the adjective lenites. Use this for physical appearance and <i>feictear dom</i> for opinion — they are not interchangeable.", see:["Feictear dom / tchítear dom"] },
{ ga:"mar is ceart", en:"properly, correctly", cat:"gram",
  note:"Literally “as is right”. Also <b>mar is cóir</b>. The negative version, <i>níl sé ag caint mar is ceart</i>, is the sentence that starts most arguments about dialect." },
{ ga:"dá gcuid féin", en:"of their own", cat:"gram",
  note:"Three pieces fused: <i>de</i> + <i>a</i> (their) + <i>féin</i>. <i>De + a</i> contracts to <b>dá</b>, and the mutation tells you whose: <i>dá chuid féin</i> (his), <i>dá cuid féin</i> (her), <i>dá gcuid féin</i> (their). <i>Cuid</i> is used with things not inherently yours — <i>mo chuid airgid</i>, <i>do chuid Gaeilge</i>.", see:["cuid mhór"] },
{ ga:"ba chlasaicí, ba chultúrtha, ba mhíne", en:"it was more classical, more cultured, more refined", cat:"gram",
  note:"Three past comparatives in a row, all with <i>ba</i> + lenition. <i>Mín</i> = smooth, fine, refined — <i>ba mhíne</i>. A rhetorical triple of the kind that earns marks in an essay.", noq:true },
{ ga:"chuir sé leis amach anseo", en:"he added to it for the future", cat:"gram",
  note:"<b>Cuir le</b> = to add to, to build on: <i>cur le do chuid scileanna</i> = to build up your skills. <b>Amach anseo</b> = from here on, in future." },
{ ga:"Sin a ndeir sé", en:"that's all he says", cat:"gram", see:["‘a’ na huilíochta","Sin a dtuigim"] },
{ ga:"Beidh orm imeacht", en:"I'll have to go", cat:"gram",
  note:"Obligation in the future uses <b>bí ar</b>, not <i>éigean</i>: <i>beidh orm, bhí orm, tá orm</i>.", see:["b’éigean dom"] },
{ ga:"an chéad réimniú / an dara réimniú", en:"the first / second conjugation", cat:"teanga",
  note:"Two conjugations plus eleven irregular verbs, and the quickest test is the future: an <b>f</b> means first conjugation (<i>molfaidh</i>), a long <b>ó/eo</b> means second (<i>ceannóidh, baileoidh</i>). First = one-syllable roots; second = roots in <i>-igh</i> and the syncopating ones in <i>-ir, -il, -in, -is</i> (<i>imir, oscail, labhair, inis</i>).", see:["Mol"] },
{ ga:"na briathra neamhrialta", en:"the irregular verbs", cat:"teanga",
  note:"Eleven of them: <i>bí, abair, beir, clois/cluin, déan, faigh, feic, ith, tabhair, tar, téigh</i>. Between them they cover most of what you say in a day, which is exactly why they stayed irregular — high-frequency verbs resist tidying up." },
];

